   604→
   605→  if (!roster || roster.length === 0) {
   606→    return (
   607→      <div className="p-4 border-t border-zinc-700 text-center">
   608→        <p className="text-zinc-500 text-sm">No roster defined for {team?.displayName || teamKey}</p>
   609→        <p className="text-xs text-zinc-600 mt-1">Use "Import from Virtius" below to add athletes</p>
   610→      </div>
   611→    );
   612→  }
   613→
   614→  return (
   615→    <div className="p-4 border-t border-zinc-700">
   616→      <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-2 max-h-64 overflow-y-auto">
   617→        {roster.map((athlete, idx) => (
   618→          <div
   619→            key={idx}
   620→            className="flex items-center gap-2 p-2 bg-zinc-700/50 rounded"
   621→          >
   622→            <div className="w-8 h-8 bg-zinc-600 rounded-full flex items-center justify-center overflow-hidden flex-shrink-0">
   623→              {athlete.hasHeadshot ? (
   624→                <img src={athlete.headshotUrl} alt={athlete.name} className="w-8 h-8 object-cover" />
   625→              ) : (
   626→                <UserGroupIcon className="w-4 h-4 text-zinc-500" />
   627→              )}
   628→            </div>
   629→            <span className="text-xs text-zinc-300 truncate flex-1">{athlete.name}</span>
   630→            {athlete.hasHeadshot ? (
   631→              <CheckCircleIcon className="w-3 h-3 text-green-500 flex-shrink-0" />
   632→            ) : (
   633→              <XCircleIcon className="w-3 h-3 text-red-500 flex-shrink-0" />
   634→            )}
   635→          </div>
   636→        ))}
   637→      </div>
   638→    </div>
   639→  );
   640→}
